from batch07 import *
start('nat','NAT — translacje i droga powrotna','4.1',['https://www.cisco.com/c/en/us/support/docs/ip/network-address-translation-nat/221481-8605-13.html','https://www.cisco.com/c/en/us/support/docs/ip/network-address-translation-nat/13779-clear-nat-comments.html','https://www.cisco.com/c/en/us/support/docs/ip/network-address-translation-nat/218012-troubleshoot-network-address-translation.html'],True)
q('NAT nie jest routingiem','Czy samo skonfigurowanie NAT zapewnia trasę do zewnętrznego serwera?','Nie',['Tak, NAT zawsze dodaje domyślną trasę|Konfiguracja translacji nie jest konfiguracją routingu.','Tak, jeśli ACL ma permit any|Selektor NAT nie tworzy drogi do celu.','Tak, gdy użyto overload|PAT również wymaga poprawnego przekazywania.'],'Translacja i wybór drogi są odrębnymi warunkami łączności.')
q('NAT nie jest firewallem','Czy statyczne mapowanie NAT 1:1 samo jest kompletną polityką bezpieczeństwa dla serwera?','Nie',['Tak, każda translacja uwierzytelnia użytkownika|NAT nie jest authentication.','Tak, wszystkie niebezpieczne porty są automatycznie rozpoznane|NAT nie zna pełnej polityki aplikacyjnej.','Tak, NAT automatycznie włącza inspekcję stanową|Zależy to od osobnych funkcji urządzenia.'],'Dostęp do publikowanej usługi kontroluje się odpowiednią polityką, nie samą zmianą adresu.')
c('Statyczny port HTTPS','W klasycznym IOS inside source static TCP opublikuj 10.0.10.10:443 pod 203.0.113.10:8443. Adresy wpisano; uzupełnij porty.','R1(config)# ip nat inside source static tcp 10.0.10.10 {{b0}} 203.0.113.10 {{b1}}',['443','8443'],'Pierwszy port należy do inside local, a drugi do reprezentacji inside global w tej komendzie.')
q('Odpowiedź do adresu globalnego','Serwer zewnętrzny odpowiada do inside global klienta. Jaki warunek jest konieczny poza samym wpisem translacji?','Ruch powrotny musi dotrzeć do właściwego urządzenia NAT',['Każdy router w Internecie musi znać prywatny adres klienta|Zewnętrzna droga korzysta z adresu globalnego.','Klient musi mieć to samo MAC co serwer|MAC ma znaczenie lokalne dla łącza.','Wszystkie urządzenia muszą mieć tę samą maskę|Nie jest to wymaganie między zdalnymi sieciami.'],'Wpis NAT nie pomoże, jeśli odpowiedź nie przejdzie przez właściwy punkt translacji.')
c('PAT na pulę','Istnieją ACL 15 i pula PUBLIC. Włącz inside source NAT z tej listy do puli z możliwością współdzielenia adresów.','R1(config)# ip nat inside source list {{b0}} pool PUBLIC {{b1}}',['15','overload'],'Overload umożliwia rozróżnianie translacji m.in. portami, zamiast wymagać osobnego adresu dla każdego hosta.')
q('Różne sesje jednego hosta','Czy jeden host może mieć wiele wpisów PAT dla różnych sesji?','Tak',['Nie, PAT zawsze ma dokładnie jeden wpis na hosta|Wpisy mogą rozróżniać protokół i porty.','Tylko jeśli zmieni adres MAC|To nie warunek różnych sesji transportowych.','Nie, bo wszystkie sesje używają jednego portu|Porty i cele mogą się różnić.'],'Liczba translacji nie jest po prostu liczbą hostów w LAN-ie.')
q('Dynamic mapping in use','IOS odmawia usunięcia puli komunikatem o używanych translacjach. Co to wskazuje?','Istnieją aktywne powiązania zależne od zmienianej konfiguracji',['Pula jest szyfrowana i nigdy nie może być zmieniona|To nie znaczenie komunikatu.','Na pewno brakuje DNS|Komunikat dotyczy użycia mapowania.','Wszystkie interfejsy są fizycznie down|Nie wynika to z tego komunikatu.'],'Zmianę trzeba zaplanować wraz z obsługą istniejących sesji i wpływu na ich działanie.')
q('Czyszczenie translacji','Dlaczego clear ip nat translation * należy stosować świadomie?','Może przerwać aktywne sesje zależne od usuniętych translacji',['Bo zmienia wszystkie hasła|Nie jest to polecenie zmiany haseł.','Bo zawsze kasuje running-config|Nie jest poleceniem kasowania konfiguracji.','Bo dodaje nowe VLAN-y|Nie dotyczy bazy VLAN.'],'Czyszczenie stanu nie jest neutralnym odczytem; podczas diagnostyki najpierw zbiera się dowody.')
c('Zmiana mapowania w labie','W izolowanym labie bez aktywnych sesji usuń mapowanie 10.0.20.10 → 203.0.113.20 i dodaj 10.0.20.20 → 203.0.113.20.','R1(config)# no ip nat inside source static {{b0}} 203.0.113.20\nR1(config)# ip nat inside source static {{b1}} {{b2}}',[(['10.0.20.10'],'ipv4'),(['10.0.20.20'],'ipv4'),(['203.0.113.20'],'ipv4')],'Usunięcie starego mapowania i dodanie nowego to odrębne operacje; wymagają kontroli konfliktów i sesji.')
q('Wpis jest, usługa nie działa','Oczekiwana translacja istnieje, lecz aplikacja nie działa. Co dalej?','Sprawdzić filtry, routing, odpowiedź serwera i drogę powrotną',['Uznać, że aplikacja na pewno działa|Wpis potwierdza tylko część mechanizmu.','Od razu zwiększyć pulę bez sprawdzenia|Brak dowodu wyczerpania puli.','Usunąć wszystkie adresy inside|To nie celowana diagnostyka.'],'Istnienie translacji nie jest dowodem poprawności całej sesji aplikacyjnej.')
c('LAN, WAN i stan','Na G0/0 oznacz inside, na G0/1 outside i wyświetl statystyki NAT. Pozostała polityka już istnieje.','R1(config)# interface GigabitEthernet0/0\nR1(config-if)# ip nat {{b0}}\nR1(config-if)# exit\nR1(config)# interface GigabitEthernet0/1\nR1(config-if)# ip nat {{b1}}\nR1(config-if)# end\nR1# show ip nat {{b2}}',['inside','outside','statistics'],'Błędne role interfejsów mogą uniemożliwiać zastosowanie oczekiwanej polityki klasycznego NAT.')
q('Nadmiar selektora','ACL wybierająca źródła do NAT obejmuje całą 10.0.0.0/8, choć wymagano tylko 10.50.0.0/24. Jakie jest ryzyko?','Translacja także niezamierzonych źródeł pasujących do polityki',['Automatyczne szyfrowanie pozostałych sieci|NAT nie szyfruje.','Usunięcie całej tablicy routingu|To nie konieczny skutek szerokiego selektora.','Brak jakiegokolwiek wpływu, wildcard jest komentarzem|Wildcard rzeczywiście uczestniczy w dopasowaniu.'],'Zakres selektora powinien odpowiadać zamierzonemu ruchowi, z uwzględnieniem pełnych warunków polityki.')
q('Pula bez overload','Pula ma trzy dostępne adresy, NAT dynamiczny 1:1 bez overload. Trzy hosty mają aktywne mapowania. Czego potrzebuje czwarty host?','Wolnego mapowania/adresu w puli',['Może zawsze współdzielić adres automatycznie|Bez overload nie zakłada się PAT.','Tylko innego MAC dla tej samej sesji|MAC nie tworzy dodatkowego adresu puli.','Zawsze wystarczy większy TTL|TTL nie zwiększa zasobów NAT.'],'Bez PAT dostępna liczba adresów ogranicza liczbę równoczesnych przydziałów 1:1.')
q('Asymetria i drugi NAT','Żądanie przeszło przez R1 NAT, odpowiedź wraca przez niezależny R2 bez tego stanu. Co może się stać?','Odpowiedź może nie znaleźć właściwej translacji',['R2 zawsze zna automatycznie wszystkie wpisy R1|Synchronizacja stanu wymaga odpowiedniej funkcji/projektu.','Każdy pakiet sam zawiera całą tabelę NAT|Pakiet nie przenosi takiej tabeli.','NAT zawsze usuwa asymetrię routingu|Nie zapewnia automatycznie symetrycznej ścieżki.'],'Przy urządzeniach stanowych trzeba projektować ścieżki i ewentualną synchronizację stanu.')
c('Sprawdź cały kontekst','Pokaż tabelę translacji, statystyki NAT oraz ACL wybierającą ruch o numerze 15.','R1# show ip nat {{b0}}\nR1# show ip nat {{b1}}\nR1# show ip access-lists {{b2}}',['translations','statistics','15'],'Zestawienie dopasowań selektora i translacji jest lepsze niż wniosek oparty na jednym liczniku.')
q('Adres z konfiguracji a osiągalność','Ustawiono inside global 203.0.113.50, lecz sieć zewnętrzna nie kieruje tego adresu do NAT. Co trzeba zapewnić?','Poprawną osiągalność tego adresu od strony zewnętrznej',['Tylko zmianę nazwy puli|Nazwa nie tworzy routingu ani ARP.','Wyłącznie większe hasło administratora|Nie dotyczy drogi do adresu.','Tylko większy limit hostów DHCP|Nie zapewnia dostępności adresu globalnego.'],'Sposób dostarczenia ruchu do adresu globalnego zależy od topologii i konfiguracji zewnętrznej.')
c('Nowa polityka PAT','ACL 25 wybiera zamierzony LAN. Włącz PAT na adresie G0/1 i pokaż translacje oraz statystyki. Role inside/outside i routing już ustawiono.','R1(config)# ip nat inside source list 25 interface GigabitEthernet0/1 {{b0}}\nR1(config)# end\nR1# show ip nat {{b1}}\nR1# show ip nat {{b2}}',['overload','translations','statistics'],'Weryfikuj po wygenerowaniu pasującego ruchu; sam wpis konfiguracji nie gwarantuje dynamicznej translacji.')
q('Dane w treści aplikacji','Dlaczego translacja nagłówka IP nie zawsze wystarcza aplikacji, która wysyła prywatny adres we własnej treści?','Adres wewnątrz danych aplikacji może wymagać osobnej obsługi lub zmiany projektu',['NAT automatycznie rozumie każdą zaszyfrowaną aplikację|Nie ma takiej gwarancji.','Każda aplikacja zawsze używa wyłącznie nagłówka IP|Niektóre przekazują adresy w danych.','UDP nie ma adresów IP|UDP jest przenoszone przez IP.'],'Obsługa protokołów aplikacyjnych przez NAT jest zależna od platformy i konkretnego protokołu.')
end()
